<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/layout.php'; require_login(); require_perm(can('clients')?'clients':'clients_view'); $pdo=pdo(); $st=$pdo->prepare('SELECT * FROM clients WHERE id=?'); $st->execute([getv('id')]); $c=$st->fetch(); $hist=$pdo->prepare("SELECT r.*, CONCAT(v.marque,' ',v.modele,' - ',v.immatriculation) voiture FROM reservations r JOIN voitures v ON v.id=r.voiture_id WHERE r.client_id=? ORDER BY r.id DESC"); $hist->execute([getv('id')]); render_header('Profil client'); ?><section class="panel"><div class="panel-head"><h2><?=e($c['nom'].' '.$c['prenom'])?></h2><a class="btn" onclick="window.print()">Imprimer profil</a></div><div class="info-grid"><p><b>Téléphone:</b> <?=e($c['telephone'])?></p><p><b>Email:</b> <?=e($c['email'])?></p><p><b>Nationalité:</b> <?=e($c['nationalite'])?></p><p><b>CIN/Passeport:</b> <?=e($c['cin'] ?: $c['passport'])?></p><p><b>Permis:</b> <?=e($c['numero_permis'])?></p><p><b>Adresse:</b> <?=e($c['adresse'])?></p></div><h3>Historique des locations</h3><table><thead><tr><th>Référence</th><th>Véhicule</th><th>Période</th><th>Total</th><th>Contrat</th></tr></thead><tbody><?php foreach($hist as $r):?><tr><td><?=e($r['reference'])?></td><td><?=e($r['voiture'])?></td><td><?=e($r['date_debut'])?> → <?=e($r['date_fin'])?></td><td><?=money($r['total'])?></td><td><a href="/contrat.php?id=<?=$r['id']?>" target="_blank">ouvrir</a></td></tr><?php endforeach;?></tbody></table></section><?php render_footer(); ?>
